import sqlite3

SKEMA = """
CREATE TABLE kelas (id INTEGER PRIMARY KEY, nama TEXT);
CREATE TABLE siswa (
    id INTEGER PRIMARY KEY,
    nama TEXT,
    kelas_id INTEGER REFERENCES kelas(id)
);
INSERT INTO kelas VALUES (1, 'XI RPL 1');
"""


def coba(nyalakan):
    db = sqlite3.connect(":memory:")
    if nyalakan:
        db.execute("PRAGMA foreign_keys = ON")   # tepat sesudah connect
    db.executescript(SKEMA)
    status = db.execute("PRAGMA foreign_keys").fetchone()[0]
    try:
        db.execute("INSERT INTO siswa (nama, kelas_id) VALUES ('Bayu', 99)")
        print(f"foreign_keys={status}: siswa di kelas 99 diterima")
    except sqlite3.IntegrityError as e:
        print(f"foreign_keys={status}: ditolak ({e})")
    db.close()


