class GagalSerialisasi(Exception):
    """Meniru error 40001 dari database: transaksi harus diulang dari awal."""


sisa_bentrok = 2                # anggap dua percobaan pertama bentrok


def transfer():
    global sisa_bentrok
    if sisa_bentrok > 0:
        sisa_bentrok -= 1
        raise GagalSerialisasi("could not serialize access")
    return "transfer berhasil"


def dengan_ulang(fungsi, maks=5, jeda_awal=0.05):
    for ke in range(1, maks + 1):
        try:
            hasil = fungsi()
            print(f"percobaan {ke}: {hasil}")
            return hasil
        except GagalSerialisasi as e:
            jeda = jeda_awal * 2 ** (ke - 1)
            print(f"percobaan {ke}: gagal ({e}), ulang sesudah {jeda:.2f} detik")
            # di kode sungguhan: time.sleep(jeda) ditambah sedikit acak
    raise RuntimeError("menyerah sesudah beberapa percobaan")


dengan_ulang(transfer)

import hashlib
import sqlite3

MIGRASI = {
    1: "CREATE TABLE pelanggan (id INTEGER PRIMARY KEY, nama TEXT NOT NULL)",
    2: "ALTER TABLE pelanggan ADD COLUMN no_hp TEXT",
    3: "CREATE INDEX idx_pelanggan_hp ON pelanggan (no_hp)",
}


def sidik(sql):
    return hashlib.sha256(sql.encode()).hexdigest()[:12]


def jalankan(db, migrasi):
    db.execute("CREATE TABLE IF NOT EXISTS schema_version (versi INTEGER PRIMARY KEY, sidik TEXT)")
    sudah = dict(db.execute("SELECT versi, sidik FROM schema_version"))
    for versi in sorted(migrasi):
        sql = migrasi[versi]
        if versi in sudah:
            if sudah[versi] != sidik(sql):
                raise RuntimeError(f"migrasi {versi} sudah pernah jalan, tapi isinya diubah")
            continue
        db.execute("BEGIN")             # migrasi dan catatannya masuk bersamaan
        try:
            db.execute(sql)
            db.execute("INSERT INTO schema_version VALUES (?, ?)", (versi, sidik(sql)))
            db.execute("COMMIT")
        except Exception:
            db.execute("ROLLBACK")
            raise
        print("jalankan migrasi", versi)


db = sqlite3.connect(":memory:", isolation_level=None)
jalankan(db, MIGRASI)
jalankan(db, MIGRASI)                   # kedua kalinya nggak ada yang dijalankan
