memtable = {}
sstable = []   # tiap SSTable: daftar (kunci, nilai) terurut
BATAS = 3      # memtable di-flush begitu berisi 3 kunci
HAPUS = None   # tombstone: penanda kunci sudah dihapus


def put(kunci, nilai):
    global memtable
    memtable[kunci] = nilai
    if len(memtable) >= BATAS:
        sstable.append(sorted(memtable.items()))   # flush ke disk
        memtable = {}


def get(kunci):
    if kunci in memtable:
        return memtable[kunci]
    for tabel in reversed(sstable):                # yang terbaru dulu
        for k, v in tabel:
            if k == kunci:
                return v
    return None


def compaction():
    gabung = {}
    for tabel in sstable:                          # yang lama ditimpa
        gabung.update(tabel)
    hidup = [(k, v) for k, v in sorted(gabung.items()) if v is not HAPUS]
    sstable[:] = [hidup]


put("a", 1)
put("b", 2)
put("c", 3)
put("a", 10)
put("b", HAPUS)
put("d", 4)
for nomor, tabel in enumerate(sstable, 1):
    print(f"SSTable {nomor}:", tabel)
print("get a:", get("a"), "| get b:", get("b"), "| get c:", get("c"))
compaction()
print("sesudah compaction:", sstable)

